import datetime
import urllib.parse

from dateutil import relativedelta
from django.db import IntegrityError
from django.db.models import Q
from django.http import Http404
from django.shortcuts import redirect, render
from rest_framework.generics import CreateAPIView, GenericAPIView

from short_links.models import ShortLink
from short_links.serializers import ShortLinkSerializer
from utils.detect_bot import detect_bot


class ShortLinkCreateView(CreateAPIView):
    queryset = ShortLink.objects.all()
    serializer_class = ShortLinkSerializer

    def post(self, request, *args, **kwargs):
        days = request.data.get('days', None)
        if days:
            request.data['active_until'] = datetime.datetime.now() + relativedelta.relativedelta(days=days)
        return self.create(request, *args, **kwargs)


class ShortLinkRedirectView(GenericAPIView):
    lookup_field = 'short_link'
    authentication_classes = ()
    permission_classes = ()

    def get_queryset(self):
        return ShortLink.objects.filter(Q(active_until__isnull=True) | Q(active_until__gt=datetime.datetime.now()))

    def get(self, request, *args, **kwargs):
        short_link: ShortLink = self.get_object()

        ua = request.META.get('HTTP_USER_AGENT')
        if ua and detect_bot(ua):
            url_parsed = urllib.parse.urlparse(short_link.link)
            # Короткие ссылки в БД содержат ссылки на yandex метрику с последующими редиректами
            # код ниже ломает рендер превью для них, т.к. редирект не происходит
            if 'appmetrica' not in url_parsed.hostname:
                url_parsed = url_parsed._replace(path='', params='', query='', fragment='')

            redirect_url = urllib.parse.urlunparse(url_parsed)
            return redirect(redirect_url)

        short_link.add_redirect_count()
        return redirect(short_link.link)


def short_links_main(request):
    """
    Обработчик страницы /short_links/
    GET: Отображает страницу сокращения большого количества ссылок
    POST: Принимает данные из формы и возвращает список сокращенных ссылок в виде строки
    """
    if not request.user.is_authenticated or not request.user.is_staff:
        raise Http404()

    if request.method != 'POST':
        return render(request, 'short_links_main.html')

    links_str = request.POST.get('links', '')
    if not links_str:
        return render(request, 'short_links_main.html', {'err': 'Ошибка! Ни одной ссылки не было загружено.'})

    short_link_length = int(request.POST.get('short_link_length', 5))
    links = links_str.split()
    exist_links = {
        obj.link: obj.get_full_short_link()
        for obj in ShortLink.objects.filter(
            link__in=links,
            active_until__isnull=True,
            short_link_length=short_link_length,
            short_link_domain=ShortLink.get_domain(request),
        )
    }

    short_links = []
    links_to_create = []
    for link in links:
        if link in exist_links.keys():
            short_links.append(exist_links[link])
            continue
        short_link_obj = ShortLink(
            link=link,
            short_link=ShortLink.get_random_string(short_link_length),
            short_link_length=short_link_length,
            short_link_domain=ShortLink.get_domain(request),
            created_by=request.user,
        )
        short_links.append(short_link_obj.get_full_short_link())
        links_to_create.append(short_link_obj)

    try:
        ShortLink.objects.bulk_create(links_to_create)
    except IntegrityError:
        return render(request, 'short_links_main.html', {'exception': 'Возникла ошибка. Попробуйте ещё раз.'})

    return render(
        request,
        'short_links_main.html',
        {
            'links_str': links_str,
            'short_links_as_text': '\n'.join(short_links),
        },
    )

