def run(sql):
    body = json.dumps({"queries":[{"refId":"A","datasource":{"type":"grafana-clickhouse-datasource","uid":"wZzPhtpSk"},"rawSql":sql}],"from":"now-1h","to":"now"})
    r = subprocess.run(["/home/user/.pi/agent/skills/grafana-api/scripts/grafana.py","POST","ds/query",body], capture_output=True, text=True)
    data = json.loads(r.stdout)
    res = data.get("results",{}).get("A",{})
    if "error" in res:
        return None, "ERR: " + res["error"][:250]
    fr = res["frames"][0]
    names = [f["name"] for f in fr["schema"]["fields"]]
    types = [f["type"] for f in fr["schema"]["fields"]]
    vals = fr["data"]["values"]
    return (names, types, vals), None

def substitute(sql, domain_mode):
    sql = sql.replace("$__timeFilter(datetime)",
                      "(datetime >= now() - INTERVAL 24 HOUR AND datetime <= now())")
    # client-side substitution: All -> raw allValue ('All'); option -> quoted value
    sql = sql.replace("$domain", "'All'" if domain_mode == "All" else "'pd.tc'")
    return sql

def show(kind, title, names, types, vals):
    n = len(vals[0]) if vals else 0
    print(f"\n### {title}  [{kind}]  rows={n}")
    print("    fields:", ", ".join(f"{a}({b})" for a, b in zip(names, types)))
    if n == 0:
        print("    !! EMPTY")
        return
    if kind in ("stat",):
        for i, nm in enumerate(names):
            v = vals[i][0] if vals[i] else None
            print(f"    {nm} = {v!r}")
    elif kind == "barchart":
        for r in range(min(n, 8)):
            print("   ", " | ".join(str(vals[i][r]) for i in range(len(names))))
        if n > 8: print("    ...")
    elif kind == "table":
        for r in range(min(n, 10)):
            print("   ", " | ".join(str(vals[i][r]) for i in range(len(names))))
        if n > 10: print("    ...")
    else:  # timeseries
        # show first + last 3 rows, values rounded
        rows = list(range(0, min(3, n))) + (list(range(max(n-3, 3), n)) if n > 3 else [])
        for r in rows:
            line = []
            for i in range(len(names)):
                v = vals[i][r]
                if isinstance(v, float): v = round(v, 3)
                line.append(str(v))
            print("   ", " | ".join(line))
        if n > 6: print("    ...")

for p in d["panels"]:
    if p.get("type") == "row":
        continue
    ttype = p["type"]
