"""Shared HTTP layer + output contract for the grafana-api skill scripts.

Env overrides:
  GRAFANA_HOST        host[:port] (default grafana-platform.medrocket.ru);
                      also names the default token dir: ~/.tokens/$HOST/token.txt
  GRAFANA_TOKEN_FILE  full override of the token file
  GRAFANA_SCHEME      http|https (default https)

Output contract (implemented by the raw CLI grafana.py and by call()):
  stdout  response body ONLY (empty on 204) — pipe straight into jq, no stripping
  stderr  one line per call: "HTTP <status> <METHOD> /api/<path>"
  exit    0 on 2xx
          1 on other HTTP statuses
          2 usage / token error
          3 transport error (DNS / TLS / timeout)
"""
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

DEFAULT_HOST = "grafana-platform.medrocket.ru"
DEFAULT_SCHEME = "https"
DEFAULT_TIMEOUT = 60


class TransportError(Exception):
    """DNS / TLS / connection / timeout failure (not an HTTP status)."""


def host():
    return os.environ.get("GRAFANA_HOST", DEFAULT_HOST)


def scheme():
    return os.environ.get("GRAFANA_SCHEME", DEFAULT_SCHEME)


def token_file():
    return os.environ.get(
        "GRAFANA_TOKEN_FILE",
        os.path.expanduser("~/.tokens/%s/token.txt" % host()),
    )


def token():
    try:
        with open(token_file()) as f:
            return f.read().strip()
    except OSError as e:
        print("Error: cannot read token %s: %s" % (token_file(), e), file=sys.stderr)
        sys.exit(2)


def request(method, path, body=None, params=None, headers=None, timeout=DEFAULT_TIMEOUT):
    """One API call. `path` is relative to /api (leading slash optional).

    body:   dict/list (JSON-encoded) or str (sent verbatim) or None.
    params: dict (urlencoded) or str (appended verbatim — for pre-encoded
            query strings) or None.
    headers: extra headers merged over the auth header.

    Returns (status:int, body:str). Raises TransportError on network failure.
    """
    url = "%s://%s/api/%s" % (scheme(), host(), path.lstrip("/"))
    if params:
        url += "?" + (params if isinstance(params, str)
                      else urllib.parse.urlencode(params))
    data = None
    hdrs = {"Authorization": "Bearer " + token()}
    if body is not None:
        data = (body if isinstance(body, str)
                else json.dumps(body, ensure_ascii=False)).encode("utf-8")
        hdrs["Content-Type"] = "application/json"
    if headers:
        hdrs.update(headers)
    req = urllib.request.Request(url, data=data, method=method.upper(), headers=hdrs)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:  # must precede URLError (it's a subclass)
        return e.code, e.read().decode("utf-8", "replace")
    except urllib.error.URLError as e:
        raise TransportError(str(getattr(e, "reason", e)))
    except (TimeoutError, ConnectionError, OSError) as e:
        raise TransportError(str(e))


def call(method, path, body=None, params=None, headers=None, timeout=DEFAULT_TIMEOUT):
    """request() with the helper contract, for use inside the CLI scripts:

    - prints "HTTP <status> <METHOD> /api/<path>" to stderr on every call;
    - 2xx:      returns the body string;
    - non-2xx:  prints "Error: ..." plus the body to stderr, exit 1;
    - transport: prints "Error: ..." to stderr, exit 3.
    """
    try:
        status, raw = request(method, path, body=body, params=params,
                              headers=headers, timeout=timeout)
    except TransportError as e:
        print("Error: request failed (network/TLS/timeout): %s /api/%s: %s"
              % (method.upper(), path, e), file=sys.stderr)
        sys.exit(3)
    print("HTTP %d %s /api/%s" % (status, method.upper(), path), file=sys.stderr)
    if not 200 <= status < 300:
        print("Error: %s /api/%s -> HTTP %d" % (method.upper(), path, status),
              file=sys.stderr)
        if raw:
            print(raw, file=sys.stderr)
        sys.exit(1)
    return raw


def report_and_exit(method, path, status, raw):
    """Terminal output for the RAW CLI (grafana.py): body on stdout (even on
    4xx — the caller may want to inspect it), status line on stderr,
    contract exit code."""
    if raw:
        sys.stdout.write(raw if raw.endswith("\n") else raw + "\n")
    print("HTTP %d %s /api/%s" % (status, method.upper(), path), file=sys.stderr)
    sys.exit(0 if 200 <= status < 300 else 1)

