# --------------------------------------------------- per-DS query mechanics
#
# The request body for POST /api/ds/query is NOT uniform across data source
# types on this platform build (verified failures, see verified.json):
#   * classic PostgreSQL (sqlds): rawSql + rawQuery + format (a STRING)
#   * ClickHouse: rawSql ALONE — a string `format` 500s with
#     "cannot unmarshal string into Go struct field Query.format", and a
#     `query` field alone reaches the server as an empty query.
# Verified facts live in scripts/verified.json (machine-readable, shared by
# all scripts) — update that file when you verify something new, not only
# the SKILL.md prose.

def verified():
    """Load scripts/verified.json (per-DS-type facts). {} when absent/invalid."""
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "verified.json")
    try:
        with open(p) as f:
            return json.load(f)
    except (OSError, json.JSONDecodeError):
        return {}


def is_clickhouse(ds_type):
    return "clickhouse" in (ds_type or "")


def build_query_body(ds_type, ds_uid, sql, fmt="table"):
    """One entry for the `queries` list of POST /api/ds/query, shaped for the
    data source TYPE (see module note above)."""
    base = {"refId": "A", "datasource": {"type": ds_type, "uid": ds_uid},
            "rawSql": sql}
    if is_clickhouse(ds_type):
        return base
    return dict(base, rawQuery=True, format=fmt,
                intervalMs=3600000, maxDataPoints=330)


def run_query(ds_type, ds_uid, sql, tfrom="now-24h", tto="now",
              fmt="table", timeout=DEFAULT_TIMEOUT):
    """POST /api/ds/query with the per-type body shape. Returns
    (frame|None, error|None) — frame is results.A.frames[0]. Never exits;
    the CLI wrappers decide what an error means."""
    body = {"queries": [build_query_body(ds_type, ds_uid, sql, fmt)],
            "from": tfrom, "to": tto}
    try:
        status, raw = request("POST", "ds/query", body=body, timeout=timeout)
    except TransportError as e:
        return None, "transport: %s" % e
    if not 200 <= status < 300:
        return None, "HTTP %d: %s" % (status, raw[:300])
    try:
        res = json.loads(raw).get("results", {}).get("A", {})
    except json.JSONDecodeError:
        return None, "non-JSON response: %s" % raw[:200]
    if res.get("error"):
        return None, res["error"]
    frames = res.get("frames") or []
    return (frames[0] if frames else None), None


def resolve_time(spec: str) -> str:
    """Resolve a Grafana-style time spec ('now-1d', ISO) to
    'YYYY-MM-DD HH:MM:SS' (UTC)."""
    m = re.fullmatch(r"now(?:-([0-9]+)([mhdwMy]))?", spec.strip())
    if m:
        n, unit = int(m.group(1) or 0), m.group(2) or "s"
        delta = {
            "s": timedelta(seconds=n), "m": timedelta(minutes=n), "h": timedelta(hours=n),
            "d": timedelta(days=n), "w": timedelta(weeks=n), "M": timedelta(days=30 * n),
            "y": timedelta(days=365 * n),
        }[unit]
        now = datetime.now(timezone.utc)
        return (now - delta).strftime("%Y-%m-%d %H:%M:%S")
    return spec.strip()

