                    print("ERR  %-38s mode=%-16s empty frame" % (label, combo_label(combo)))
                    continue
                vals = frame.get("data", {}).get("values") or []
                rows = frame.get("length") or (len(vals[0]) if vals else 0)
                if p.get("type") == "timeseries":
                    f0 = frame["schema"]["fields"][0] if frame.get("schema", {}).get("fields") else {}
                    if f0.get("type") != "time":
                        bad += 1
                        print("ERR  %-38s first field %r is %r, not time — timeseries axis will not render"
                              % (label, f0.get("name"), f0.get("type")))
                if sample is None and vals and (len(vals) > 1 and vals[1] or vals[0]):
                    col = vals[1] if len(vals) > 1 and vals[1] else vals[0]
                    sample = col[0] if col else None
            failures += bad
            if bad == 0:
                print("OK   %-38s runs=%-4d rows=%-5s value=%r" % (label, len(combos), rows, sample))
    print("validate %s: %d targets, %d query runs, %d failures" %
          (src_desc, target_count, total_runs, failures))
    return 1 if (failures or var_errors) else 0


def main(argv=None):

if args.cmd == "search":
    return cmd_search(args)
if args.cmd == "pull":
    return cmd_pull(args)
if args.cmd == "find":
    return cmd_find(args)
if args.cmd == "validate":
    return cmd_validate(args)

def cmd_pull(args):
    """Pull a deployed dashboard to a file ready for the next import: the
    stale numeric `id` is stripped (id + foreign uid = import rejected),
    while `uid` and the server's current `version` are kept as-is (a file
    with a mismatched version is rejected by overwrite=true too)."""
    dash = get_dashboard(args.uid)["dashboard"]
    dash.pop("id", None)
    out = json.dumps(dash, ensure_ascii=False, indent=1)
    if args.out:
        with open(args.out, "w") as f:
            f.write(out + "\n")
        print("pulled uid=%s version=%s -> %s (ready for import)" %
              (args.uid, dash.get("version"), args.out))
    else:
        print(out)
    return 0


def _safe_get_dashboard(uid):
    try:
        status, raw = g.request("GET", "dashboards/uid/%s" % uid)
    except g.TransportError:
        return None
    if 200 <= status < 300:
        return json.loads(raw).get("dashboard")
    return None


def cmd_find(args):
    """Find panels of a given type across ALL visible dashboards — the
    deterministic way to copy a fleet-verified panel shape instead of
    inventing settings this build may reject. --json prints the full JSON of
    the first match (fieldConfig/options/targets included) for extraction."""
    raw = g.call("GET", "search", params={"query": "", "perpage": 200, "type": "dash-db"})
    dashes = json.loads(raw)
    hits = []
    for d in dashes:
        dash = _safe_get_dashboard(d.get("uid"))
        if not dash:
            continue
        stack = list(dash.get("panels", []))
        while stack:
            p = stack.pop(0)
            if p.get("type") == args.type:
                ds_ref = json.dumps(p.get("datasource") or {}, sort_keys=True)
                if args.ds and args.ds not in ds_ref:
                    continue
                hits.append((d.get("title"), d.get("uid"), p))
            stack.extend(p.get("panels", []))
    if not hits:
        print("no %s panels found in any of the %d visible dashboards" % (args.type, len(dashes)))
        return 1
    if args.json:
        print(json.dumps(hits[0][2], ensure_ascii=False, indent=2))
    else:
        for title, uid, p in hits:
            print("%-16s %-45s %s" % (uid, title, p.get("title", "")))
    return 0


def _datasource_by_ref(ref, cache):
    """Resolve a {type,uid} | {type,name} | 'name-or-uid' datasource reference
    to (uid, type). A plain string is looked up in the DS listing."""
    if isinstance(ref, dict) and ref.get("uid"):
        return ref.get("uid"), ref.get("type") or "grafana-postgresql-datasource"
    name_or_uid = ref if isinstance(ref, str) else (ref or {}).get("name") or (ref or {}).get("uid")
    if not name_or_uid:
        return None, None
    if "_ds" not in cache:
        try:
            cache["_ds"] = json.loads(g.call("GET", "datasources"))
        except SystemExit:
            cache["_ds"] = []
    for s in cache["_ds"]:
        if s.get("uid") == name_or_uid or s.get("name") == name_or_uid:
            return s.get("uid"), s.get("type")
    return name_or_uid, "grafana-postgresql-datasource"


def _var_modes(dash, tfrom, tto, timeout, ds_cache):
    """Execute every query/custom variable and return {name: [(label, substitution), ...]}
    (the All mode first when includeAll). Per-type substitution rule, in code:
      classic PostgreSQL: option values quoted ('val'), allValue raw
      ClickHouse:         everything raw — option values must CARRY their own
                          quotes (built in the variable query, char(39) pattern)
    Also returns a list of human-readable errors for variables that failed."""
    modes, errors = {}, []
    for v in dash.get("templating", {}).get("list", []):
        name = v.get("name")
        if not name or name.startswith("_"):
            continue
        if v.get("type") == "custom":
            opts = [x.get("value") if isinstance(x, dict) else x for x in v.get("values", [])]
            quoted = False
        elif v.get("type") == "query" and v.get("query"):
            ds_uid, ds_type = _datasource_by_ref(v.get("datasource"), ds_cache)
            if not ds_uid:
                errors.append("variable %r: no datasource to run against" % name)
                continue
            frame, err = g.run_query(ds_type, ds_uid, v["query"], tfrom=tfrom, tto=tto, timeout=timeout)
            if err:
                errors.append("variable %r: %s" % (name, err[:150]))
                continue
            opts = [str(x) for x in frame["data"]["values"][0]] if frame and frame.get("data", {}).get("values") else []
            quoted = not g.is_clickhouse(ds_type)
        else:
            continue
        entries = []
        if v.get("includeAll") or v.get("type") == "query":
            entries.append(("All", v.get("allValue") or ("'All'" if quoted else "All")))
        for o in opts:
            entries.append((o, ("'%s'" % o.replace("'", "''")) if quoted else o))
        if entries:
            modes[name] = entries
    return modes, errors


def _substitute(sql, combo, from_iso, to_iso, names):
    """Interpolate macros + variables the way Grafana does at render time."""
    sql = re.sub(r"\$__timeFilter\(([^)]+)\)",
                 r"(\1 >= '%s' AND \1 <= '%s')" % (from_iso, to_iso), sql)
    sql = re.sub(r"\$\{__from:date[^}]*\}", from_iso, sql)
    sql = re.sub(r"\$\{__to:date[^}]*\}", to_iso, sql)
    for name in sorted(names, key=len, reverse=True):  # longest first: $domain2 before $domain
        if name in combo:
            sql = sql.replace("$%s" % name, combo[name])
    return sql


def cmd_validate(args):
    """Run every panel query with every variable combination. OK/ERR per
    target, timeseries x-axis (first field must be field type 'time') checked
    explicitly. Exit 1 on any failure — wire this into the import workflow."""
    if args.target and os.path.isfile(args.target):
        dash = load_dashboard_file(args.target)
        src_desc = args.target
    else:
        dash = get_dashboard(args.target)["dashboard"]
        src_desc = "uid %s" % args.target

    from_iso, to_iso = g.resolve_time(args.tfrom), g.resolve_time(args.tto)
    ds_cache = {}
    var_modes, var_errors = _var_modes(dash, args.tfrom, args.tto, args.timeout, ds_cache)
    for e in var_errors:
        print("WARN variable: %s" % e)
    names = list(var_modes)

    baseline = {n: var_modes[n][0][1] for n in names}
    if args.full:
        combos = [dict(zip(names, vals))
                  for vals in itertools.product(*[[val for _, val in var_modes[n]] for n in names])]
    else:
        combos = [dict(baseline)]
        for n in names:  # one variable at a time, the rest at baseline (All)
            for label, val in var_modes[n][1:]:
                m = dict(baseline); m[n] = val
                combos.append(m)

    def combo_label(combo):
        diff = {n: v for n, v in combo.items() if baseline.get(n) != v}
        return ",".join("%s=%s" % (n, v) for n, v in diff.items()) or "all"

    total_runs = failures = target_count = 0
    for p in dash.get("panels", []):
        for t in p.get("targets", []):
            sql = t.get("rawSql") or t.get("rawQuery")
            if not sql:
                continue
            target_count += 1
            ds_uid, ds_type = _datasource_by_ref(t.get("datasource") or p.get("datasource"), ds_cache)
            if not ds_uid:
                failures += 1
                print("ERR  %s [%s]: no datasource on target" % (p.get("title"), t.get("refId", "?")))
                continue
            label = "%s [%s]" % (p.get("title"), t.get("refId", "?"))
            bad = 0
            rows = None
            sample = None
            for combo in combos:
                s2 = _substitute(sql, combo, from_iso, to_iso, names)
                frame, err = g.run_query(ds_type, ds_uid, s2, tfrom=args.tfrom, tto=args.tto,
                                         timeout=args.timeout)
                total_runs += 1
                if err:
                    bad += 1
                    print("ERR  %-38s mode=%-16s %s" % (label, combo_label(combo), err[:160]))
                    continue
                if frame is None:
                    bad += 1
                    print("ERR  %-38s mode=%-16s empty frame" % (label, combo_label(combo)))
                    continue
                vals = frame.get("data", {}).get("values") or []
                rows = frame.get("length") or (len(vals[0]) if vals else 0)
                if p.get("type") == "timeseries":
                    f0 = frame["schema"]["fields"][0] if frame.get("schema", {}).get("fields") else {}
                    if f0.get("type") != "time":
                        bad += 1
                        print("ERR  %-38s first field %r is %r, not time — timeseries axis will not render"
                              % (label, f0.get("name"), f0.get("type")))
                if sample is None and vals and (len(vals) > 1 and vals[1] or vals[0]):
                    col = vals[1] if len(vals) > 1 and vals[1] else vals[0]
                    sample = col[0] if col else None
            failures += bad
            if bad == 0:
                print("OK   %-38s runs=%-4d rows=%-5s value=%r" % (label, len(combos), rows, sample))
    print("validate %s: %d targets, %d query runs, %d failures" %
          (src_desc, target_count, total_runs, failures))
    return 1 if (failures or var_errors) else 0


